use super::*;
use crate::position::AccountPosition;
use crate::payoff::Strategy;

pub(crate) fn why_target(a: &AccountPosition, strategy: Strategy, as_of: &str, promo_ends: &[(String, String)], urgency_days: i64) -> String {
    if promo_state_of(&a.account, as_of, promo_ends, urgency_days) == PromoState::Expiring {
        return format!("its 0% rate ends {} and the whole balance begins accruing at once", promo_end_for(&a.account, promo_ends).unwrap_or(""));
    }
    if strategy == Strategy::Avalanche {
        return match a.apr {
            None => "it is the largest debt with no known rate, which is the one most likely to be the expensive one".to_string(),
            Some(apr) => format!("it carries the highest known rate at {}%, so every dollar here saves the most interest", (apr * 10_000.0).round() / 100.0),
        };
    }
    "it is the smallest balance, so it clears soonest and its minimum rolls into the next one".to_string()
}
